WITH with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, device_code, reading_ts, temp_c, status_bits, firmware, prev_reading_ts, session_start_flag, session_id, CASE WHEN device_code RLIKE '^(DV-03|DV-02)$' THEN 'GROUP_B' WHEN device_code RLIKE '^(DV-01|DV-04)$' THEN 'CORE' ELSE 'PRIORITY' END AS device_code_zone FROM islands ORDER BY device_code DESC;
